CREATE TABLE IF NOT EXISTS memories (id VARCHAR(36), team_id VARCHAR(36) NOT NULL, scope VARCHAR(16) NOT NULL, owner_id VARCHAR(36) DEFAULT '' NOT NULL, title VARCHAR(160) NOT NULL, summary VARCHAR(300) NOT NULL, content TEXT NOT NULL, refs TEXT NOT NULL, `status` VARCHAR(16) NOT NULL, origin VARCHAR(16) NOT NULL, author_id VARCHAR(36) NOT NULL, session_id VARCHAR(36) NULL, supersedes_id VARCHAR(36) NULL, expires_at BIGINT NULL, version INT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, last_read_at BIGINT NULL, read_count INT DEFAULT 0 NOT NULL, CONSTRAINT pk_memories PRIMARY KEY (id), CONSTRAINT fk_memories_team_id__id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX memory_visible ON memories (team_id, scope, owner_id, `status`, updated_at);
CREATE TABLE IF NOT EXISTS memory_tags (memory_id VARCHAR(36), tag VARCHAR(40), team_id VARCHAR(36) NOT NULL, scope VARCHAR(16) NOT NULL, owner_id VARCHAR(36) DEFAULT '' NOT NULL, CONSTRAINT pk_memory_tags PRIMARY KEY (memory_id, tag), CONSTRAINT fk_memory_tags_memory_id__id FOREIGN KEY (memory_id) REFERENCES memories(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX memory_tag_lookup ON memory_tags (team_id, scope, owner_id, tag, memory_id);
